let mockState={provider:"mock",id:"mock-vm",status:"STOPPED",gpu:"Mock GPU",vcpu:4,memoryGb:16,volumeGb:50,costPerHour:0};
class MockProvider{async status(){return mockState}async start(){mockState={...mockState,status:"RUNNING"};return mockState}async stop(){mockState={...mockState,status:"STOPPED"};return mockState}async restart(){mockState={...mockState,status:"RUNNING"};return mockState}}
class RunPodProvider{constructor(env){if(!env.RUNPOD_API_KEY)throw new Error("RUNPOD_API_KEY_NOT_CONFIGURED");if(!env.RUNPOD_POD_ID)throw new Error("RUNPOD_POD_ID_NOT_CONFIGURED");this.base="https://rest.runpod.io/v1";this.key=env.RUNPOD_API_KEY;this.podId=env.RUNPOD_POD_ID}async request(path,method="GET"){const response=await fetch(`${this.base}${path}`,{method,headers:{Authorization:`Bearer ${this.key}`,Accept:"application/json"}});if(!response.ok){const body=await response.text();throw new Error(`RUNPOD_${response.status}:${body.slice(0,300)}`)}if(response.status===204)return{};return await response.json()}normalize(pod){return{provider:"runpod",id:pod.id??this.podId,status:pod.desiredStatus??"UNKNOWN",gpu:pod.gpu?.displayName??null,vcpu:pod.vcpuCount??null,memoryGb:pod.memoryInGb??null,volumeGb:pod.volumeInGb??null,costPerHour:pod.adjustedCostPerHr??pod.costPerHr??null}}async status(){return this.normalize(await this.request(`/pods/${encodeURIComponent(this.podId)}`))}async start(){await this.request(`/pods/${encodeURIComponent(this.podId)}/start`,"POST");return this.status()}async stop(){await this.request(`/pods/${encodeURIComponent(this.podId)}/stop`,"POST");return this.status()}async restart(){await this.request(`/pods/${encodeURIComponent(this.podId)}/restart`,"POST");return this.status()}}
async function agentRequest(env,path,method="GET",body){if(!env.VM_AGENT_URL)throw new Error("VM_AGENT_URL_NOT_CONFIGURED");const base=env.VM_AGENT_URL.replace(/\/$/,"");const headers=new Headers({Accept:"application/json"});if(body!==undefined)headers.set("Content-Type","application/json");if(env.VM_AGENT_TOKEN)headers.set("Authorization",`Bearer ${env.VM_AGENT_TOKEN}`);const response=await fetch(`${base}${path}`,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});const text=await response.text();let data=text;try{data=text?JSON.parse(text):null}catch{}if(!response.ok)throw new Error(`VM_AGENT_${response.status}:${text.slice(0,300)}`);return data}
const API_VERSION="0.1.0",PREFIX="/api/v1",corsHeaders={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Authorization, Content-Type","Access-Control-Allow-Methods":"GET, POST, OPTIONS"};
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{...corsHeaders,"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}})}
function provider(env){return env.VM_PROVIDER==="runpod"?new RunPodProvider(env):new MockProvider()}
function authorized(request,env){if(!env.APP_API_TOKEN)return true;return request.headers.get("Authorization")===`Bearer ${env.APP_API_TOKEN}`}
async function bodyJson(request){const type=request.headers.get("Content-Type")??"";if(!type.includes("application/json"))return{};try{const parsed=await request.json();return parsed&&typeof parsed==="object"?parsed:{}}catch{return{}}}
function errorResponse(error){const message=error instanceof Error?error.message:String(error),configError=message.includes("NOT_CONFIGURED");return json({ok:false,error:message,code:configError?"NOT_CONFIGURED":"INTERNAL_ERROR"},configError?503:500)}
async function route(request,env){const url=new URL(request.url),path=url.pathname.replace(/\/+$/,"")||"/",method=request.method.toUpperCase();if(method==="OPTIONS")return new Response(null,{status:204,headers:corsHeaders});if(path==="/")return json({ok:true,service:"vm-cloud-api",version:API_VERSION,provider:env.VM_PROVIDER??"mock",security:env.APP_API_TOKEN?"token":"open-prototype"});if(path===`${PREFIX}/health`&&method==="GET")return json({ok:true,data:{status:"online",time:new Date().toISOString()}});if(!path.startsWith(PREFIX))return json({ok:false,error:"ROUTE_NOT_FOUND",code:"NOT_FOUND"},404);if(!authorized(request,env))return json({ok:false,error:"ACCESS_DENIED",code:"UNAUTHORIZED"},401);try{const cloud=provider(env);if(path===`${PREFIX}/vm/status`&&method==="GET")return json({ok:true,data:await cloud.status()});if(path===`${PREFIX}/vm/start`&&method==="POST")return json({ok:true,data:await cloud.start()});if(path===`${PREFIX}/vm/stop`&&method==="POST")return json({ok:true,data:await cloud.stop()});if(path===`${PREFIX}/vm/restart`&&method==="POST")return json({ok:true,data:await cloud.restart()});if(path===`${PREFIX}/session/create`&&method==="POST"){const now=Date.now();return json({ok:true,data:{sessionId:crypto.randomUUID(),createdAt:new Date(now).toISOString(),expiresAt:new Date(now+3600000).toISOString(),vm:await cloud.status()}},201)}if(path===`${PREFIX}/game/status`&&method==="GET")return json({ok:true,data:await agentRequest(env,"/game/status")});if(path===`${PREFIX}/game/start`&&method==="POST")return json({ok:true,data:await agentRequest(env,"/game/start","POST",await bodyJson(request))});if(path===`${PREFIX}/game/stop`&&method==="POST")return json({ok:true,data:await agentRequest(env,"/game/stop","POST",await bodyJson(request))});if(path===`${PREFIX}/stream/status`&&method==="GET")return json({ok:true,data:await agentRequest(env,"/stream/status")});if(path===`${PREFIX}/stream/start`&&method==="POST")return json({ok:true,data:await agentRequest(env,"/stream/start","POST",await bodyJson(request))});if(path===`${PREFIX}/stream/stop`&&method==="POST")return json({ok:true,data:await agentRequest(env,"/stream/stop","POST",await bodyJson(request))});return json({ok:false,error:"ROUTE_NOT_FOUND",code:"NOT_FOUND"},404)}catch(error){return errorResponse(error)}}
export default{async fetch(request,env){return route(request,env)}};
